function HomeMainUpdatePosNode:__init()
    self._rootUINode = nil                          --根节点
    self._mainChapterNode = nil                     --主线按钮
    self._mainChapterOffPos = Vector3(0, 198, 0)
    self._worldBossNode = nil
    self._climbTowerNode = nil
end

function HomeMainUpdatePosNode:__delete()
    self._rootUINode = nil       --根节点
    self._mainChapterNode = nil
    self._mainChapterOffPos = nil
    self._worldBossNode = nil
    self._climbTowerNode = nil
end

function HomeMainUpdatePosNode:Awake()
    self._behaviourAction = KTool.GetComponent(self.controller.gameObject, typeof(BehaviourAction))
end

function HomeMainUpdatePosNode:Start()
    ---@type Engine.Lib.BehaviourAction
    local  behaviourAction = self._behaviourAction
    behaviourAction.UpdateAction = function()
        self:OnUpdate()
    end
end

function HomeMainUpdatePosNode:InitNode(rootUINode)
    self._rootUINode = rootUINode
    self._mainChapterNode = rootUINode.transform:Find("ChapterBtnContainer/BtnMainChapter")
    self._worldBossNode = rootUINode.transform:Find("ChapterBtnContainer/BtnWorldBoss")
    self._climbTowerNode = rootUINode.transform:Find("ChapterBtnContainer/BtnClimbTower")
end

