--更新ui坐标
function HomeMainUpdatePosNode:UpdateUIPos()
    if isNull(self._rootUINode) then
        return
    end

    if not isNull(self._mainChapterNode) then
        local pos = CfUtils.UIWorldToScreenPos(self.controller.gameObject, self._rootUINode.gameObject, KTool.FindCameraForLayer(CS.UnityEngine.LayerMask.NameToLayer('Default')))
        self._mainChapterNode.transform.anchoredPosition = Vector3(pos.x, pos.y, 0) + self._mainChapterOffPos
    end

    if not isNull(self._worldBossNode) then
        local pos = CfUtils.UIWorldToScreenPos(self.rukou_02_point.gameObject, self._rootUINode.gameObject, KTool.FindCameraForLayer(CS.UnityEngine.LayerMask.NameToLayer('Default')))
        self._worldBossNode.transform.anchoredPosition = Vector3(pos.x, pos.y, 0)
    end

    if not isNull(self._climbTowerNode) then
        local pos = CfUtils.UIWorldToScreenPos(self.rukou_01_point.gameObject, self._rootUINode.gameObject, KTool.FindCameraForLayer(CS.UnityEngine.LayerMask.NameToLayer('Default')))
        self._climbTowerNode.transform.anchoredPosition = Vector3(pos.x, pos.y, 0)
    end
end

function HomeMainUpdatePosNode:OnDestroy()
    ---@type Engine.Lib.BehaviourAction
    local behaviourAction = self._behaviourAction
    behaviourAction.FixedUpdateAction = nil
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
    self = nil
end

return HomeMainUpdatePosNode